    if (v) {
        v = v.replaceAll(/\.0$/, '')
        if (v.matches(/^\d{8}$/)) {
            def yyyy = v.substring(0, 4)
            def mm = v.substring(4, 6) == "00" ? "01" : v.substring(4, 6)
            def dd = v.substring(6, 8) == "00" ? "01" : v.substring(6, 8)
            v = "${yyyy}-${mm}-${dd}"
        } else if (v.contains('-')) {
            v = v.replaceAll(/-00-/, '-01-').replaceAll(/-00$/, '-01')
            v = v.replace(' ', 'T')
        }
        m.put(k, v)
    }
}

// ----------------------
// 3. ID 및 속성 설정
// ----------------------
def idVal = m.get('id')
if (idVal != null) m.put('es_id', idVal.toString())
m.put('run_id', attributes?.get('run_id')?.toString() ?: null)
m.put('batch_id', attributes?.get('batch_id')?.toString() ?: null)

// ----------------------
// 4. author/publisher 로직
// ----------------------
['author', 'publisher'].each { fieldName ->
    def val = m.get(fieldName)?.toString()?.trim()
    def aliases = []
    def exact = []

    if (val && val != '-') {
        m.put(fieldName, val)
        aliases = val.split(/\s*\|\s*/).collect { it.trim() }.findAll { it && it != '-' }
        exact = aliases.collect {
            it.toLowerCase().replaceAll(/[^\p{L}\p{N}]+/, '')
        }.findAll { it }
    } else {
        m.put(fieldName, null)
    }
    m.put(fieldName + "_aliases", aliases.toArray(new String[0]))
    m.put(fieldName + "_exact", exact.toArray(new String[0]))
}

// ----------------------
// 5. 스키마 확장
// ----------------------
def originalFields = new ArrayList(record.getSchema().getFields())
def existingFieldNames = originalFields.collect { it.getFieldName() }.toSet()

['content_plain', 'es_id', 'run_id', 'batch_id'].each { f ->
    if (!existingFieldNames.contains(f)) {
        originalFields.add(new RecordField(f, RecordFieldType.STRING.getDataType()))
