import org.apache.nifi.serialization.record.MapRecord
import org.apache.nifi.serialization.record.RecordField
import org.apache.nifi.serialization.record.RecordFieldType
import org.apache.nifi.serialization.SimpleRecordSchema

def m = new LinkedHashMap(record.toMap())

// ----------------------
// 1️⃣ DataContents 정제 (태그 제거 및 자간 보정)
// ----------------------
def raw = m.get('DataContents')?.toString()
if (raw != null) {
    def plain = raw
        .replaceAll('(?is)<script[^>]*>.*?</script>', ' ')
        .replaceAll('(?is)<style[^>]*>.*?</style>', ' ')
        .replaceAll('(?is)', ' ')
        .replaceAll('(?is)<[^>]+>', '') 
        .replaceAll('\\u00A0|\\u200B|\\uFEFF', '')
        .replaceAll('(?<=\\b\\p{L}\\b)\\s+(?=\\b\\p{L}\\b)', '')
        .replaceAll('\\s+', ' ').trim()
    m.put('DataContentsPlain', plain)
} else {
    m.put('DataContentsPlain', null)
}

// ----------------------
// 2️⃣ 날짜 문자열 정리 (MM/DD/YYYY -> YYYY-MM-DD 변환 추가)
// ----------------------
['ModifyDate', 'ApproveDate'].each { k ->
    def v = m.get(k)?.toString()?.trim()
    if (v) {
        v = v.replaceAll(/\.0$/, '') // .0 제거

        // A. "MM/DD/YYYY HH:mm:ss" 형식 처리
        if (v.contains('/')) {
            def parts = v.split(' ') // [0]: 02/25/2026, [1]: 16:18:39
            def dateParts = parts[0].split('/') // [0]: 02, [1]: 25, [2]: 2026

            if (dateParts.size() == 3) {
                def yyyy = dateParts[2]
                def mm = dateParts[0] == "00" ? "01" : dateParts[0]
                def dd = dateParts[1] == "00" ? "01" : dateParts[1]

                def timePart = parts.size() > 1 ? "T" + parts[1] : ""
                v = yyyy + "-" + mm + "-" + dd + timePart
            }
        }
        // B. 8자리 숫자(YYYYMMDD) 형식 처리 (혹시 몰라 유지)
        else if (v.matches(/^\d{8}$/)) {
            def yyyy = v.substring(0, 4)
            def mm = v.substring(4, 6) == "00" ? "01" : v.substring(4, 6)
            def dd = v.substring(6, 8) == "00" ? "01" : v.substring(6, 8)
            v = yyyy + "-" + mm + "-" + dd
        }
        // C. 이미 하이픈이 있는 경우 00 보정 및 T 치환
        else if (v.contains('-')) {
            v = v.replaceAll(/-00-/, '-01-').replaceAll(/-00$/, '-01').replace(' ', 'T')
        }

        m.put(k, v)
    }
}

// ----------------------
// 3️⃣ ES ID 및 4️⃣ Attributes 설정 (기존 로직 유지)
// ----------------------
def idVal = m.get('NewsItemId')
if (idVal != null) m.put('es_id', idVal.toString())

m.put('run_id', attributes?.get('run_id')?.toString() ?: null)
m.put('batch_id', attributes?.get('batch_id')?.toString() ?: null)

// ✅ 스키마 동적 확장
def originalFields = new ArrayList(record.getSchema().getFields())
def existingFieldNames = originalFields.collect { it.getFieldName() }.toSet()

['data_contents_plain', 'es_id', 'run_id', 'batch_id'].each { f ->
    if (!existingFieldNames.contains(f)) {
        originalFields.add(new RecordField(f, RecordFieldType.STRING.getDataType()))
    }
}

return new MapRecord(new SimpleRecordSchema(originalFields), m)

import java.time.LocalDate
import java.time.format.DateTimeFormatter

def ff = session.get()
if (!ff) return
def fmt = DateTimeFormatter.ofPattern("yyyyMMdd")

def runMode = (ff.getAttribute("run_mode") ?: "inc").toLowerCase()
def fullStart = ff.getAttribute("full_start_date") ?: "20250101"
def thisRun = ff.getAttribute("this_run") ?: (LocalDate.now().format(fmt) + "000000")
def thisDate = thisRun.substring(0, 8)

def rawLastRun = ff.getAttribute("last_run")
def invalidLastRun = (rawLastRun == null || rawLastRun.trim().isEmpty() || rawLastRun.startsWith("\${") || rawLastRun.length() < 8 || !(rawLastRun.substring(0,8) ==~ /\d{8}/))
def lastRun = invalidLastRun ? (fullStart + "000000") : rawLastRun

def batchId = ff.getAttribute("batch_id") ?: java.util.UUID.randomUUID().toString()
def serviceKey = ff.getAttribute("service_key")
def currIndex = ff.getAttribute("currIndex") ?: ""
def systemAlias = ff.getAttribute("system_alias") ?: ""

if (serviceKey == null || serviceKey.trim().isEmpty()) {
    session.transfer(ff, REL_FAILURE)
    return
}

LocalDate start = LocalDate.parse(runMode == "full" ? fullStart : lastRun.substring(0, 8), fmt)
LocalDate finalEnd = LocalDate.parse(thisDate, fmt)

// 총 윈도우 수 계산
int cnt = 0
LocalDate temp = start
while (!temp.isAfter(finalEnd)) {
    LocalDate e = temp.plusDays(2)
    if (e.isAfter(finalEnd)) e = finalEnd
    cnt++
    temp = e.plusDays(1)
}


ff = session.putAttribute(ff, "role", "manager") // 반장 표시
ff = session.putAttribute(ff, "batch_id", batchId)
ff = session.putAttribute(ff, "window_count", String.valueOf(cnt))
ff = session.putAttribute(ff, "currIndex", currIndex)
ff = session.putAttribute(ff, "system_alias", systemAlias)
session.transfer(ff, REL_SUCCESS)


LocalDate c = start
while (!c.isAfter(finalEnd)) {
    LocalDate e = c.plusDays(2)
    if (e.isAfter(finalEnd)) e = finalEnd

    def out = session.create()
    out = session.putAttribute(out, "role", "worker") 
    out = session.putAttribute(out, "service_key", serviceKey)
    out = session.putAttribute(out, "start_date", c.format(fmt))
    out = session.putAttribute(out, "end_date", e.format(fmt))
    out = session.putAttribute(out, "batch_id", batchId)
    out = session.putAttribute(out, "window_count", String.valueOf(cnt))
    out = session.putAttribute(out, "currIndex", currIndex)
    out = session.putAttribute(out, "system_alias", systemAlias)
    out = session.putAttribute(out, "this_run", thisRun)
    session.transfer(out, REL_SUCCESS)
    c = e.plusDays(1)
}

