def invalidLastRun = (rawLastRun == null || rawLastRun.trim().isEmpty() || rawLastRun.startsWith("\${") || rawLastRun.length() < 8 || !(rawLastRun.substring(0,8) ==~ /\d{8}/))
def lastRun = invalidLastRun ? (fullStart + "000000") : rawLastRun

def batchId = ff.getAttribute("batch_id") ?: java.util.UUID.randomUUID().toString()
def serviceKey = ff.getAttribute("service_key")
def currIndex = ff.getAttribute("currIndex") ?: ""
def systemAlias = ff.getAttribute("system_alias") ?: ""

if (serviceKey == null || serviceKey.trim().isEmpty()) {
    session.transfer(ff, REL_FAILURE)
    return
}

LocalDate start = LocalDate.parse(runMode == "full" ? fullStart : lastRun.substring(0, 8), fmt)
LocalDate finalEnd = LocalDate.parse(thisDate, fmt)

// 총 윈도우 수 계산
int cnt = 0
LocalDate temp = start
while (!temp.isAfter(finalEnd)) {
    LocalDate e = temp.plusDays(2)
    if (e.isAfter(finalEnd)) e = finalEnd
    cnt++
    temp = e.plusDays(1)
}


ff = session.putAttribute(ff, "role", "manager") // 반장 표시
ff = session.putAttribute(ff, "batch_id", batchId)
ff = session.putAttribute(ff, "window_count", String.valueOf(cnt))
ff = session.putAttribute(ff, "currIndex", currIndex)
ff = session.putAttribute(ff, "system_alias", systemAlias)
session.transfer(ff, REL_SUCCESS)


LocalDate c = start
while (!c.isAfter(finalEnd)) {
    LocalDate e = c.plusDays(2)
    if (e.isAfter(finalEnd)) e = finalEnd

    def out = session.create()
    out = session.putAttribute(out, "role", "worker") // 실무자 표시
    out = session.putAttribute(out, "service_key", serviceKey)
    out = session.putAttribute(out, "start_date", c.format(fmt))
    out = session.putAttribute(out, "end_date", e.format(fmt))
    out = session.putAttribute(out, "batch_id", batchId)
    out = session.putAttribute(out, "window_count", String.valueOf(cnt))
    out = session.putAttribute(out, "currIndex", currIndex)
    out = session.putAttribute(out, "system_alias", systemAlias)
    out = session.putAttribute(out, "this_run", thisRun)
    session.transfer(out, REL_SUCCESS)
    c = e.plusDays(1)
}

