import org.apache.nifi.serialization.record.MapRecord
import org.apache.nifi.serialization.record.RecordField
import org.apache.nifi.serialization.record.RecordFieldType
import org.apache.nifi.serialization.SimpleRecordSchema

def m = new LinkedHashMap(record.toMap())

// 1. content_plain 생성 (content 원본 유지, HTML 태그 제거)
def raw = m.get('content')?.toString()
if (raw != null) {
    def plain = raw
        .replaceAll('(?is)<script[^>]*>.*?</script>', ' ')
        .replaceAll('(?is)<style[^>]*>.*?</style>', ' ')
        .replaceAll('(?is)', ' ')
        .replaceAll('(?is)<[^>]+>', ' ')
        .replaceAll('\\s+', ' ')
        .trim()
    m.put('content_plain', plain)
} else {
    m.put('content_plain', null)
}

// 2. 날짜 .0 제거 및 공백을 'T'로 치환 (ES ISO-8601 포맷 맞춤)
['start_dttm', 'update_dttm'].each { k ->
    def v = m.get(k)
    if (v != null) {
        // .0을 제거하고, 날짜와 시간 사이의 공백을 'T'로 변환
        def formattedDate = v.toString().trim().replaceAll(/\.0$/, '').replace(' ', 'T')
        m.put(k, formattedDate)
    }
}

// 3. ES ID 설정
def idVal = m.get('id')
if (idVal != null) {
    m.put('es_id', idVal.toString())
}

// 4. attributes -> record
def runId = attributes?.get('run_id')
if (runId != null && runId.toString().trim()) {
    m.put('run_id', runId.toString())
}

def batchId = attributes?.get('batch_id')
if (batchId != null && batchId.toString().trim()) {
    m.put('batch_id', batchId.toString())
}

// 5. 스키마 동적 확장 (새로 추가한 필드들을 스키마에 반영)
def originalFields = new ArrayList(record.getSchema().getFields())
def existingFieldNames = originalFields.collect { it.getFieldName() }.toSet()

// 새롭게 생성한 필드 이름들을 배열로 선언하고 스키마에 추가
['content_plain', 'es_id', 'run_id', 'batch_id'].each { fieldName ->
    if (!existingFieldNames.contains(fieldName)) {
        originalFields.add(new RecordField(fieldName, RecordFieldType.STRING.getDataType()))
    }
}

// 확장된 스키마를 씌워서 새로운 MapRecord 반환
return new MapRecord(new SimpleRecordSchema(originalFields), m)
